import os, re

root = "/Users/mcneillm/Documents/Projects/repo-memory-plugin"
file_imports = {}

for dirpath, dirnames, filenames in os.walk(root):
    if "/.git" in dirpath:
        continue
    for f in filenames:
        if f.endswith(".go"):
            fpath = os.path.join(dirpath, f)
            with open(fpath, "r", encoding="utf-8") as fh:
                lines = fh.readlines()

            in_import_block = False
            imports = []
            for line in lines:
                stripped = line.strip()
                if stripped.startswith("import ("):
                    in_import_block = True
                    continue
                elif in_import_block:
                    if stripped == ")":
                        in_import_block = False
                        continue
                    m = re.search(r"\"([^\"]+)\"", stripped)
                    if m:
                        imports.append(m.group(1))
                else:
                    m = re.match(r"^import\s+(?:[a-zA-Z0-9_.]+\s+)?\"([^\"]+)\"", stripped)
                    if m:
                        imports.append(m.group(1))

            antigravity_imports = [imp for imp in imports if "antigravity" in imp]
            if antigravity_imports:
                relpath = os.path.relpath(fpath, root)
                file_imports[fpath] = (relpath, antigravity_imports)

for fpath, (relpath, imps) in sorted(file_imports.items()):
